const { models } = await anna.llm.catalog({ serviceType: 'music_gen' });
const m = models.find(x => x.capabilities.lyrics) ?? models[0];

const song = await anna.music.generateAwait({
  prompt: 'melancholic cinematic piano, slow ~70 BPM, rainy night',
  lyrics: m.capabilities.lyrics ? '[Verse 1]\n…\n[Chorus]\n…' : undefined,
  model: m.modelName,
  clientTag: 'scene-3-score',
  idempotencyKey: 'canvas-node-8f3a-v2',
}, {
  onProgress: (p) => status.textContent = `${p.state} · queue ${p.progress?.queuePosition ?? '-'}`,
  signal: abortController.signal,          // → music.cancelJob
  timeoutMs: 10 * 60 * 1000,
});
audioEl.src = song.result.url;             // ~30 min TTL
audioEl.onerror = async () => { audioEl.src = await song.result.refreshUrl(); };
costEl.textContent = `${song.billedCostCU} CU`;

const job = await anna.music.getJob({ jobId });
if (job.state === 'succeeded') audioEl.src = job.result.url;
else if (job.state === 'failed') toast(`${job.error.code}: ${job.error.message}`);
